def solution():
    import sys

    data = sys.stdin.read().strip().split()
    if not data:
        return
    # First token is n, but we don't actually need to use it
    # Remaining tokens are the list elements
    # Handle possible brackets and commas in the second line
    nums = []
    for token in data[1:]:
        # Remove surrounding brackets or commas
        cleaned = token.strip('[],')
        if cleaned == '':
            continue
        try:
            nums.append(int(cleaned))
        except ValueError:
            # Skip any non-integer tokens
            continue

    even_sum = 0
    for num in nums:
        if num % 2 == 0:
            even_sum += num
    print(even_sum)

