def solution(n):
    """
    Returns "Positive", "Negative", or "Zero" depending on the integer value of *n*.
    Raises an Exception with a specific message if *n* is not an integer
    (including booleans, floats, strings, None, lists, etc.).
    """
    # Boolean values are subclasses of int in Python, but should be treated as invalid input
    if isinstance(n, bool) or not isinstance(n, int):
        raise Exception("Error: Input must be an integer.")

    if n > 0:
        return "Positive"
    elif n < 0:
        return "Negative"
    else:
        return "Zero"

