def solution():
    """
    Reads a non-negative integer n (0 <= n <= 12) from standard input
    and returns its factorial computed recursively.
    """
    import sys

    # Read and clean input
    data = sys.stdin.read().strip()
    if not data:
        return  # No input provided
    try:
        n = int(data)
    except ValueError:
        raise ValueError("Input must be an integer.")

    # Validate constraints
    if n < 0 or n > 12:
        raise ValueError("Input must satisfy 0 <= n <= 12.")

    def factorial(num: int) -> int:
        """
        Recursively computes factorial of a non-negative integer.
        Base case: factorial(0) = 1 and factorial(1) = 1.
        """
        if num <= 1:
            return 1
        return num * factorial(num - 1)

    return factorial(n)

