        return

    # Recursive helper that prints numbers from x down to 1
    def countdown(x):
        """
        Recursively prints the numbers from x down to 1, each on a new line.
        """
        if x < 1:
            return
        print(x)
        if x > 1:
            countdown(x - 1)

    # Main logic: handle invalid input or start the recursive countdown
    if n < 1:
        print("Invalid input")
    else:
        countdown(n)

