def solution():
    import sys
    # Read all input tokens
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    try:
        # First token is the size of the list
        n = int(next(it))
    except StopIteration:
        return

    # Read the list of integers
    nums = []
    for _ in range(n):
        try:
            nums.append(int(next(it)))
        except StopIteration:
            break

    # The next token is the target value
    try:
        target = int(next(it))
    except StopIteration:
        return

    # Linear search for the target
    index = -1
    for i, val in enumerate(nums):
        if val == target:
            index = i
            break

    # Output the result
    sys.stdout.write(str(index))

