def solution(n):
    """
    Return the nth Fibonacci number for 0 <= n <= 30.
    Raises ValueError if n is negative.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")

    if n < 0:
        raise ValueError("n cannot be negative")

    if n == 0:
        return 0
    if n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def solution():
    """
    Reads an integer n from stdin, computes its factorial recursively,
    and returns the result as an integer.
    Constraints: 0 ≤ n ≤ 12.
    """
    import sys

    # Read the input integer
    line = sys.stdin.readline()
    if not line:
        return

    n = int(line.strip())

    # Recursive factorial function
    def factorial(k: int) -> int:
        if k <= 1:
            return 1
        return k * factorial(k - 1)

    return factorial(n)

def solution(arr):
    """
    Return a new list containing the elements of `arr` sorted in ascending order.
    The function expects `arr` to be of type list; otherwise it raises TypeError.
    The input list is left unmodified.
    """
    if not isinstance(arr, list):
        raise TypeError("Input must be a list")
    return sorted(arr)

