def solution(n):
    """
    Return the nth Fibonacci number, where 0 <= n <= 30.
    Raises ValueError for n < 0 or n > 30.
    """
    # Validate input type and range
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0 or n > 30:
        raise ValueError("n must be between 0 and 30 inclusive")

    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Iteratively compute Fibonacci numbers using O(1) space
    prev, curr = 0, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr

