def solution(lst, threshold):
    """
    Count how many integers in `lst` are greater than `threshold`.
    Return -1 if the input list is empty, not a list, or contains
    a non‑integer element.
    """
    if not isinstance(lst, list) or not lst:
        return -1

    def helper(i):
        if i == len(lst):
            return 0
        val = lst[i]
        if not isinstance(val, int):
            return -1
        rest = helper(i + 1)
        if rest == -1:
            return -1
        return (1 if val > threshold else 0) + rest

    return helper(0)

