def solution():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    # Expect first integer to be n, then n array elements, then target
    it = iter(data)
    try:
        n = int(next(it))
    except StopIteration:
        return
    arr = []
    for _ in range(n):
        try:
            arr.append(int(next(it)))
        except StopIteration:
            break
    try:
        target = int(next(it))
    except StopIteration:
        # If target is not provided separately, assume last element of arr
        if arr:
            target = arr.pop()
            n -= 1
        else:
            return

    # Recursive binary search
    def binary_search(left, right):
        if left > right:
            return -1
        mid = (left + right) // 2
        mid_val = arr[mid]
        if mid_val == target:
            return mid
        elif mid_val < target:
            return binary_search(mid + 1, right)
        else:
            return binary_search(left, mid - 1)

    result = binary_search(0, n - 1)
    sys.stdout.write(str(result))

def solution(n):
    """
    Return the nth Fibonacci number where 0 ≤ n ≤ 30.
    Raises ValueError if n is negative or greater than 30.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0 or n > 30:
        raise ValueError("n must be between 0 and 30 inclusive")
    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 1
    # Iterative DP: keep only two previous values
    prev, curr = 0, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr

