class TestSumOfNestedLists(unittest.TestCase):
    def test_basic_flat_list(self):
        """Basic case: a simple flat list of positive integers."""
        self.assertEqual(solution([1, 2, 3, 4, 5]), 15)

    def test_empty_list(self):
        """Edge case: an empty list should return 0."""
        self.assertEqual(solution([]), 0)

    def test_single_nested_level(self):
        """List with a single level of nesting."""
        self.assertEqual(solution([1, [2, 3], 4]), 10)

    def test_multiple_nested_levels(self):
        """Nested list with multiple levels of depth."""
        nested = [1, [2, [3, 4], 5], [6], 7]
        self.assertEqual(solution(nested), 28)

    def test_negative_numbers(self):
        """List containing negative integers."""
        self.assertEqual(solution([-1, [-2, 3], 4, -5]), -1)

    def test_large_numbers(self):
        """List with integers at the upper bound of constraints."""
        large_values = [1000000, -1000000, 500000, -500000]
        self.assertEqual(solution(large_values), 0)

    def test_deep_nesting(self):
        """Deeply nested list to test recursion depth handling."""
        # Construct a list of depth 1000 where each level contains a single integer 1
        deep_list = 1
        for _ in range(1000):
            deep_list = [deep_list]
        self.assertEqual(solution(deep_list), 1)

    def test_many_elements(self):
        """Test with a large number of elements (10,000) to evaluate performance."""
        many_elements = [i % 2 for i in range(10000)]  # 0 or 1
        expected_sum = sum(many_elements)
        self.assertEqual(solution(many_elements), expected_sum)

    def test_nested_empty_lists(self):
        """List containing empty nested lists; total sum should be 0."""
        self.assertEqual(solution([[], [[], []], []]), 0)

    def test_mixed_content(self):
        """List containing a mix of integers, empty lists, and nested lists."""
        mixed = [1, [], [2, [3, []], 4], -5, [[], [6]]]
        self.assertEqual(solution(mixed), 11)

    def test_invalid_input_type(self):
        """Function should raise a TypeError when encountering a non-integer, non-list element."""
        with self.assertRaises(TypeError):
            solution([1, "two", [3]])

    def test_non_numeric_content(self):
        """Function should raise a TypeError when encountering non-numeric content inside lists."""
        with self.assertRaises(TypeError):
            solution([1, [2, [3.5]]])

    def test_string_as_list(self):
        """Function should raise a TypeError if the top-level input is not a list."""
        with self.assertRaises(TypeError):
            solution("not a list")

    def test_large_negative_numbers(self):
        """Test summing a list with large negative numbers."""
        large_negatives = [-1000000, -500000, -250000]
        self.assertEqual(solution(large_negatives), -1750000)

    def test_sum_of_zeros(self):
        """Sum of a list composed entirely of zeros."""
        zeros = [0] * 5000
        self.assertEqual(solution(zeros), 0)

    def test_single_integer(self):
        """Top-level list contains a single integer."""
        self.assertEqual(solution([42]), 42)

    def test_single_list(self):
        """Top-level list contains a single nested list."""
        self.assertEqual(solution([[1, 2, 3]]), 6)

    def test_nested_integer_list(self):
        """List contains a nested list of integers."""
        self.assertEqual(solution([1, [2, 3], [4, [5]]]), 15)

    def test_unbalanced_nesting(self):
        """Test that function correctly handles uneven nested structures."""
        uneven = [1, [2, [3, [4]], [5]], 6]
        self.assertEqual(solution(uneven), 21)

    def test_large_random_nested_list(self):
        """Test with a randomly generated nested list of moderate size."""
        import random
        def generate_nested(depth, breadth):
            if depth == 0:
                return random.randint(-1000, 1000)
            return [generate_nested(depth-1, breadth) for _ in range(breadth)]
        nested = generate_nested(5, 3)
        # Compute expected sum via a helper that directly evaluates the nested structure.
        def sum_helper(lst):
            total = 0
            for item in lst:
                if isinstance(item, int):
                    total += item
                else:
                    total += sum_helper(item)
            return total
        expected = sum_helper(nested)
        self.assertEqual(solution(nested), expected)


