def solution():
    """
    Reads an integer n and an array of n integers from standard input,
    replaces each negative number according to the rules described
    in the problem statement, sorts the resulting array in
    non‑decreasing order, and prints the sorted array as space‑
    separated integers on a single line.
    """
    import sys

    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    try:
        n = int(next(it))
    except StopIteration:
        return
    arr = []
    for _ in range(n):
        try:
            arr.append(int(next(it)))
        except StopIteration:
            break

    # Preserve the original array for reference when
    # computing replacements.
    original = arr[:]
    corrected = []

    for i in range(n):
        if original[i] >= 0:
            corrected.append(original[i])
        else:
            left_val = original[i - 1] if i > 0 and original[i - 1] > 0 else None
            right_val = original[i + 1] if i < n - 1 and original[i + 1] > 0 else None
            if left_val is None and right_val is None:
                corrected.append(0)
            else:
                total = 0
                if left_val is not None:
                    total += left_val
                if right_val is not None:
                    total += right_val
                corrected.append(total)

    corrected.sort()
    # Output as space-separated integers.
    sys.stdout.write(' '.join(map(str, corrected)))

