def solution():
    import sys

    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    try:
        n = int(next(it))
    except StopIteration:
        return

    arr = []
    for _ in range(n):
        try:
            arr.append(int(next(it)))
        except StopIteration:
            break

    try:
        target = int(next(it))
    except StopIteration:
        target = None

    if target is None:
        print(-1)
        return

    # Sort the array in non-decreasing order
    arr.sort()

    # Binary search for target
    left, right = 0, n - 1
    found_index = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            found_index = mid
            break
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    print(found_index)

def solution(*args):
    """
    Search for target in a rotated sorted array that may contain duplicates.
    The function is flexible: it can be called with explicit arguments
    (nums, target) or, if no arguments are supplied, it will read all tokens
    from standard input.  All but the last token are treated as the array
    elements, the final token is the target value.

    Returns:
        bool: True if target exists in nums, False otherwise.
    """
    # Determine input source
    if args:
        nums, target = args[0], args[1]
    else:
        import sys
        data = sys.stdin.read().strip().split()
        if not data:
            return False
        target = int(data[-1])
        nums = list(map(int, data[:-1]))

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return True

        # When duplicates make it ambiguous, shrink the window
        if nums[left] == nums[mid] == nums[right]:
            left += 1
            right -= 1
            continue

        # Left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Right half is sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return False

