def solution():
    """
    Computes the nth Fibonacci number efficiently using the fast doubling algorithm.
    Reads a single integer n from standard input and returns the nth Fibonacci number.

    The fast doubling method calculates F(n) in O(log n) time and O(1) additional space,
    making it suitable even for large n (e.g., up to 10^18 if needed).

    Returns:
        int: The nth Fibonacci number.
    """
    import sys

    # Read input
    data = sys.stdin.readline().strip()
    if not data:
        return 0
    n = int(data)

    # Fast doubling helper that returns (F(n), F(n+1))
    def fib_pair(k: int):
        if k == 0:
            return (0, 1)
        a, b = fib_pair(k >> 1)  # F(k//2), F(k//2 + 1)
        c = a * ((b << 1) - a)   # F(2k)
        d = a * a + b * b        # F(2k + 1)
        if k & 1:
            return (d, c + d)
        else:
            return (c, d)

    return fib_pair(n)[0]

