        """A single coin larger than the amount yields no combinations."""
        self.assertEqual(solution([5], 3), 0)

    def test_duplicate_coins(self):
        """Duplicate denominations should not affect the count of combinations."""
        self.assertEqual(solution([1, 1, 2], 3), 2)

