        """With only 1-valued coin, there is always exactly one combination."""
        self.assertEqual(solution([1], 2500), 1)

    def test_multiple_coins_combination(self):
        """Test a small set of coins with several possible combinations."""
        self.assertEqual(solution([1, 3, 4], 6), 4)

    def test_sorted_and_unsorted_same_result(self):
        """Ordering of coins should not affect the result."""
        self.assertEqual(solution([5, 2, 1], 5), 4)

    def test_combination_with_large_coins(self):
        """Test a moderate amount with a few large denominations."""
        self.assertEqual(solution([2, 5, 10], 100), 66)

    def test_unreachable_amount(self):
        """Coins cannot make the amount if the greatest coin is still too large."""
        self.assertEqual(solution([5, 10], 3), 0)

