        """When 1-coin is present, there are typically multiple ways."""
        self.assertEqual(solution([1, 3], 4), 2)

    def test_multiple_small_coins(self):
        """Test a common small set of denominations."""
        self.assertEqual(solution([1, 2, 3], 5), 5)

    def test_duplicate_coins_multiple_amount(self):
        """Duplicate coins with a larger amount should still count correctly."""
        self.assertEqual(solution([2, 2, 3], 6), 2)

    def test_combo_with_large_and_small(self):
        """Large coin with 1-coin should yield exactly two combinations."""
        self.assertEqual(solution([1, 5000], 5000), 2)

    def test_amount_with_no_ones(self):
        """Without a 1-coin, some amounts cannot be made."""
        self.assertEqual(solution([2, 7, 10], 5), 1)

    def test_amount_zero_with_duplicates(self):
        """Zero amount remains 1 even with many duplicate coins."""
        self.assertEqual(solution([1, 1, 1], 0), 1)

    def test_large_amount_with_mixed_coins(self):
        """A more complex scenario with a mix of small and large coins."""
        self.assertEqual(solution([1, 2, 5, 10, 20, 50], 500), 1074)

    def test_amount_exact_multiple_without_one(self):
        """An amount exactly divisible by a coin but no 1-coin exists."""
        self.assertEqual(solution([5, 10], 20), 5)

