def solution(arr):
    """
    Recursively sum all positive integers in the list.
    If a negative integer is encountered, a custom exception is raised,
    caught by the outer function, and a specific error message is returned.
    """
    # Custom exception for negative values
    class NegativeValueError(Exception):
        pass

    def _sum_positive(index):
        """
        Helper recursive function that processes arr[index:].
        Raises NegativeValueError if a negative number is found.
        """
        if index == len(arr):
            return 0
        val = arr[index]
        if val < 0:
            raise NegativeValueError
        return val + _sum_positive(index + 1)

    try:
        return _sum_positive(0)
    except NegativeValueError:
        return "Negative values are not allowed."

