            raise TypeError(f"Inner array at index {idx} is not iterable.")
        # Convert to list for easier handling
        try:
            seq = list(arr)
        except Exception:
            raise TypeError(f"Inner array at index {idx} cannot be converted to a list.")
        for elem in seq:
            # Check special numeric values
            if isinstance(elem, (int, float)):
                try:
                    f = float(elem)
                except Exception:
                    continue
                if math.isnan(f) or math.isinf(f):
                    raise ValueError("Array contains NaN or infinite value.")
            flat.append(elem)

    # ---------- Sort ----------
    # If all elements are strings, use locale-aware key;
    # otherwise, use natural ordering.
    try:
        # Attempt to detect if all elements are strings
        if all(isinstance(x, str) for x in flat):
