def _sorted_objects(arr):
    '''
    Sorts a list of dictionaries based on the criteria:
    1. 'age' (integer) ascending
    2. length of 'name' (string) ascending
    Implements merge sort to avoid using Python's built-in sort.
    '''
    def merge_sort(lst):
        if len(lst) <= 1:
            return lst
        mid = len(lst) // 2
        left = merge_sort(lst[:mid])
        right = merge_sort(lst[mid:])
        return merge(left, right)

    def merge(left, right):
        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            a = left[i]
            b = right[j]
            # Primary key: age
            if a['age'] < b['age']:
                merged.append(a)
                i += 1
            elif a['age'] > b['age']:
                merged.append(b)
                j += 1
            else:
                # Secondary key: length of name
                if len(a['name']) <= len(b['name']):
                    merged.append(a)
                    i += 1
                else:
                    merged.append(b)
                    j += 1
        # Append remaining items
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged

    sorted_arr = merge_sort(arr)
    return sorted_arr

