            size += 1
        elif cmd == 'GET_INDEX':
            if len(parts) < 2:
                out_lines.append('Index out of bounds')
                continue
            try:
                idx = int(parts[1])
            except ValueError:
                out_lines.append('Index out of bounds')
                continue
            if idx < 0 or idx >= size:
                out_lines.append('Index out of bounds')
            else:
                val = kth(root, idx)
                out_lines.append(str(val))
        else:
            # Unknown command: ignore or could output error, but spec does not mention
            pass

    sys.stdout.write('\n'.join(out_lines))

