def solution(n):
    """
    Recursively compute the sum of all integers from 1 to n.
    For n < 1 the function returns 0.

    Although the arithmetic series formula could be used directly,
    this implementation uses recursion in a divide‑and‑conquer manner
    to satisfy the “recursive without loops” requirement.

    Parameters:
        n (int): The upper bound of the summation.

    Returns:
        int: Sum of numbers from 1 to n.
    """
    if n < 1:
        return 0

    # Helper recursion that splits the range to keep depth log‑scale.
    def _recursive_sum(start, end):
        if start > end:
            return 0
        if start == end:
            return start
        mid = (start + end) // 2
        return _recursive_sum(start, mid) + _recursive_sum(mid + 1, end)

    return _recursive_sum(1, n)

def solution(n):
    """
    Recursively compute the sum of all integers from 1 to n.
    For n < 1 the function returns 0.

    The function strictly expects an integer argument; passing a float
    (or any non‑int) raises a TypeError as required by the test suite.

    Parameters:
        n (int): The upper bound of the summation.

    Returns:
        int: Sum of numbers from 1 to n.

    Raises:
        TypeError: If n is not an instance of int.
    """
    # Ensure the input is an integer; floats should trigger an error.
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")

    if n < 1:
        return 0

    def _recursive_sum(start, end):
        if start > end:
            return 0
        if start == end:
            return start
        mid = (start + end) // 2
        return _recursive_sum(start, mid) + _recursive_sum(mid + 1, end)

    return _recursive_sum(1, n)

