    Raises TypeError if the list contains mixed types.
    """
    # Validate that all elements are of the same type
    if arr:
        first_type = type(arr[0])
        for x in arr:
            if type(x) is not first_type:
                raise TypeError("All elements must be of the same type")

    from collections import deque

    class MergeQueue:
        __slots__ = ('dq',)

        def __init__(self, data):
            self.dq = deque(data)

        def has(self):
            return bool(self.dq)

        def front(self):
            return self.dq[0]

        def pop(self):
            return self.dq.popleft()

    def merge(left, right):
        lq = MergeQueue(left)
        rq = MergeQueue(right)
        merged = []
        while lq.has() or rq.has():
            if lq.has() and (not rq.has() or lq.front() <= rq.front()):
                merged.append(lq.pop())
            else:
                merged.append(rq.pop())
        return merged

    def mergesort(lst):
        n = len(lst)
        if n <= 1:
            return lst
        mid = n // 2
        left_sorted = mergesort(lst[:mid])
        right_sorted = mergesort(lst[mid:])
        return merge(left_sorted, right_sorted)

    return mergesort(arr) if arr else []

