        """Test the function with a string composed of the same character."""
        self.assertEqual(solution("aaaaa"), 5)

    def test_mixed_case_letters(self):
        """Test case sensitivity: uppercase and lowercase letters."""
        # The longest palindromic subsequence is "A a A" of length 3
        self.assertEqual(solution("AaAa"), 3)

    def test_no_longer_than_one(self):
        """Test with all distinct characters; longest subsequence length should be 1."""
        self.assertEqual(solution("abcd"), 1)

