        """Example from the problem statement (even length)."""
        self.assertEqual(solution("cbbd"), 2)

    def test_odd_length_example(self):
        """Example from the problem statement (odd length)."""
        self.assertEqual(solution("bbbab"), 4)

    def test_long_string_all_same(self):
        """Test performance and correctness on a long string of identical characters."""
        long_same = "z" * 1000
        self.assertEqual(solution(long_same), 1000)

    def test_long_string_alternating(self):
        """Test a long string with alternating characters; LPS should be half the length."""
        alternating = "ab" * 500  # length 1000
        self.assertEqual(solution(alternating), 500)

    def test_symmetric_pattern(self):
        """Test on a symmetric pattern where the whole string is a palindrome."""
        symmetric = "abcdedcba"  # length 9, palindrome
        self.assertEqual(solution(symmetric), 9)

    def test_complex_example(self):
        """Test on a known complex example from literature."""
        self.assertEqual(solution("agbdba"), 5)

    def test_empty_string(self):
        """Test the function with an empty string; expected length 0."""
        self.assertEqual(solution(""), 0)

    def test_upper_and_lower_mixed(self):
        """Test with a mix of uppercase and lowercase where longest subsequence is 3."""
        # The subsequence "A b A" (indices 0,3,4) is a palindrome of length 3
        self.assertEqual(solution("AaBbAa"), 3)

    def test_single_upper_character(self):
        """Test that a single uppercase character returns 1."""
        self.assertEqual(solution("Z"), 1)


