def solution(nums):
    # Dynamic programming solution for maximum product subarray
    if not nums:
        return 0

    max_prod = min_prod = best = nums[0]

    for num in nums[1:]:
        if num == 0:
            max_prod = 0
            min_prod = 0
        else:
            new_max = max(num, max_prod * num, min_prod * num)
            new_min = min(num, max_prod * num, min_prod * num)
            max_prod, min_prod = new_max, new_min

        if max_prod > best:
            best = max_prod

    return best

