def solution():
    import sys, re
    data = sys.stdin.read()
    if not data.strip():
        return
    nums = list(map(int, re.findall(r'-?\d+', data)))
    if len(nums) < 3:
        return
    m, n = nums[0], nums[1]
    grid_vals = nums[2:2 + m * n]
    k = nums[2 + m * n] if 2 + m * n < len(nums) else 0
    grid = [grid_vals[i * n:(i + 1) * n] for i in range(m)]

    INF = 10 ** 15
    # dp[i][j][d] = min cost to reach cell (i, j) using exactly d diagonal moves
    dp = [[[INF] * (k + 1) for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = grid[0][0]

    for i in range(m):
        for j in range(n):
            for d in range(k + 1):
                cur = dp[i][j][d]
                if cur == INF:
                    continue
                # Move down
                if i + 1 < m:
                    nd = d
                    nc = cur + grid[i + 1][j]
                    if nc < dp[i + 1][j][nd]:
                        dp[i + 1][j][nd] = nc
                # Move right
                if j + 1 < n:
                    nd = d
                    nc = cur + grid[i][j + 1]
                    if nc < dp[i][j + 1][nd]:
                        dp[i][j + 1][nd] = nc
                # Diagonal move
                if i + 1 < m and j + 1 < n and d + 1 <= k:
                    nd = d + 1
                    nc = cur + grid[i + 1][j + 1]
                    if nc < dp[i + 1][j + 1][nd]:
                        dp[i + 1][j + 1][nd] = nc

    answer = min(dp[m - 1][n - 1][d] for d in range(k + 1))
    print(answer)

def solution():
    """
    Implements a recursive sorting data structure using a randomized treap to support
    insert, delete, and get_sorted operations efficiently without using any built-in
    sorting functions.

    The treap keeps the binary search tree property on keys and heap property on
    random priorities, giving an expected O(log n) depth which keeps recursion
    safe for up to 10^6 operations.

    Input is read from standard input, output is written to standard output.
    """
    import sys
    import random

    data = sys.stdin.buffer.read().splitlines()
    if not data:
        return
    n = int(data[0])

    # Node definition for treap
    class Node:
        __slots__ = ("key", "prio", "cnt", "left", "right")

        def __init__(self, key: int):
            self.key = key
            # large random priority to keep tree balanced on average
            self.prio = random.randint(1, 1 << 30)
            self.cnt = 1          # count of duplicates
            self.left = None
            self.right = None

    # Rotations to maintain heap property
    def rotate_right(y: Node) -> Node:
        x = y.left
        y.left = x.right
        x.right = y
        return x

    def rotate_left(x: Node) -> Node:
        y = x.right
        x.right = y.left
        y.left = x
        return y

    # Insert key into treap rooted at root
    def insert(root: Node, key: int) -> Node:
        if root is None:
            return Node(key)
        if key == root.key:
            root.cnt += 1
            return root
        if key < root.key:
            root.left = insert(root.left, key)
            if root.left.prio > root.prio:
                root = rotate_right(root)
        else:
            root.right = insert(root.right, key)
            if root.right.prio > root.prio:
                root = rotate_left(root)
        return root

    # Delete one occurrence of key from treap rooted at root
    def delete(root: Node, key: int) -> Node:
        if root is None:
            return None
        if key == root.key:
            if root.cnt > 1:
                root.cnt -= 1
                return root
            # Remove the node itself
            if root.left is None and root.right is None:
                return None
            if root.left is None:
                root = rotate_left(root)
                root.left = delete(root.left, key)
            elif root.right is None:
                root = rotate_right(root)
                root.right = delete(root.right, key)
            else:
                # Both children exist: rotate with higher priority child
                if root.left.prio > root.right.prio:
                    root = rotate_right(root)
                    root.right = delete(root.right, key)
                else:
                    root = rotate_left(root)
                    root.left = delete(root.left, key)
        elif key < root.key:
            root.left = delete(root.left, key)
        else:
            root.right = delete(root.right, key)
        return root

    # In-order traversal to collect sorted keys
    def inorder(root: Node, out: list):
        if root is None:
            return
        inorder(root.left, out)
        out.extend([str(root.key)] * root.cnt)
        inorder(root.right, out)

    root = None
    output_lines = []

    for line in data[1:]:
        parts = line.split()
        cmd = parts[0]
        if cmd == b"insert":
            x = int(parts[1])
            root = insert(root, x)
        elif cmd == b"delete":
            x = int(parts[1])
            root = delete(root, x)
        else:  # get_sorted
            if root is None:
                output_lines.append("empty")
            else:
                sorted_vals = []
                inorder(root, sorted_vals)
                output_lines.append(" ".join(sorted_vals))

    sys.stdout.write("\n".join(output_lines))

def solution(arr):
    import sys
    # Increase recursion limit to safely handle deep recursion for large inputs
    sys.setrecursionlimit(200000)

    # Custom data structure to hold intermediate sorted sublists
    class MergeNode:
        __slots__ = ('sorted',)

        def __init__(self, sorted_list):
            self.sorted = sorted_list

    def merge(left: MergeNode, right: MergeNode) -> MergeNode:
        """Merge two sorted MergeNode objects into a single sorted MergeNode."""
        L, R = left.sorted, right.sorted
        i = j = 0
        merged = []

        # Standard merge step of merge sort
        while i < len(L) and j < len(R):
            if L[i] <= R[j]:
                merged.append(L[i])
                i += 1
            else:
                merged.append(R[j])
                j += 1

        # Append any remaining elements
        merged.extend(L[i:])
        merged.extend(R[j:])
        return MergeNode(merged)

    def rec(l: int, r: int) -> MergeNode:
        """Recursively split the array and merge."""
        if l == r:  # Base case: single element
            return MergeNode([arr[l]])
        mid = (l + r) // 2
        left_node = rec(l, mid)
        right_node = rec(mid + 1, r)
        return merge(left_node, right_node)

    # Handle empty input
    if not arr:
        return []

    # Start recursive merge sort
    root = rec(0, len(arr) - 1)
    return root.sorted

