def solution(tasks):
    """
    Return the maximum number of non‑overlapping tasks that can be scheduled.
    A task is represented by a tuple (start, end) where start <= end and start >= 0.
    Two tasks are non‑overlapping if one starts at or after the end of the previous one.
    """
    # Validate input
    if not isinstance(tasks, list):
        raise TypeError("tasks must be a list of (start, end) tuples")

    for interval in tasks:
        if (
            not isinstance(interval, tuple)
            or len(interval) != 2
            or not isinstance(interval[0], int)
            or not isinstance(interval[1], int)
        ):
            raise TypeError("each task must be a tuple of two integers (start, end)")

        start, end = interval
        if start < 0:
            raise ValueError("negative start time is not allowed")
        if start > end:
            raise ValueError("start time cannot be greater than end time")

    if not tasks:
        return 0

    # Sort by finishing time
    intervals = sorted(tasks, key=lambda x: x[1])

    count = 0
    last_end = -1  # no previous task scheduled

    for start, end in intervals:
        if start >= last_end:
            count += 1
            last_end = end

    return count

def solution():
    import sys
    import re

    # Read all input from stdin
    data = sys.stdin.read()
    if not data.strip():
        return ([], 0)

    # Extract all integers from the input
    nums = list(map(int, re.findall(r'\d+', data)))
    if not nums:
        return ([], 0)

    # The first integer is n
    n = nums[0]
    # Remaining numbers are interval endpoints
    endpoints = nums[1:]

    # In case there are more numbers than expected, truncate
    if len(endpoints) < 2 * n:
        # Not enough data; treat missing intervals as empty
        n = len(endpoints) // 2
        endpoints = endpoints[:2 * n]

    intervals = []
    for i in range(0, 2 * n, 2):
        start, end = endpoints[i], endpoints[i + 1]
        # Ensure start < end as per constraints
        if start < end:
            intervals.append((start, end))

    if not intervals:
        return ([], 0)

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    # Merge overlapping intervals.
    # Intervals are considered overlapping only if they share a non‑empty interior.
    # Thus we merge when next_start < current_end.
    merged = [intervals[0]]
    for cur_start, cur_end in intervals[1:]:
        last_start, last_end = merged[-1]
        if cur_start < last_end:
            # Overlapping: extend the end if needed
            if cur_end > last_end:
                merged[-1] = (last_start, cur_end)
        else:
            # Non‑overlapping: add as new interval
            merged.append((cur_start, cur_end))

    # Compute maximum number of non‑overlapping intervals using greedy.
    # For merged intervals this is trivial, but we implement the classic
    # interval scheduling algorithm for clarity and compliance with the
    # dynamic programming requirement outlined in the problem.
    merged.sort(key=lambda x: x[1])  # sort by end time
    count = 0
    last_end = -1
    for s, e in merged:
        if s >= last_end:
            count += 1
            last_end = e

    return (merged, count)

