def solution(s: str) -> int:
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(not ('a' <= c <= 'z') for c in s):
        raise ValueError("String must contain only lowercase letters")
    n = len(s)
    if n == 0:
        return 0
    dp = [0] * n
    for i in range(n - 1, -1, -1):
        dp[i] = 1
        prev = 0
        for j in range(i + 1, n):
            temp = dp[j]
            if s[i] == s[j]:
                dp[j] = prev + 2
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp
    return dp[n - 1]

import unittest
import random
import string

class TestLongestPalindromicSubsequence(unittest.TestCase):
    @staticmethod
    def _expected_lps(s: str) -> int:
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            dp[i][i] = 1
            for j in range(i + 1, n):
                if s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2 if j > i + 1 else 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
        return dp[0][n - 1] if n else 0

    def test_single_character(self):
        self.assertEqual(solution("a"), 1)

    def test_all_same_characters(self):
        s = "aaaaaa"
        expected = len(s)
        self.assertEqual(solution(s), expected)

    def test_all_different_characters(self):
        s = "abcdefg"
        self.assertEqual(solution(s), 1)

    def test_simple_palindromic_string(self):
        s = "racecar"
        self.assertEqual(solution(s), len(s))

    def test_non_palindromic_complex_string(self):
        s = "bbbab"
        expected = 4
        self.assertEqual(solution(s), expected)

    def test_random_string_small(self):
        s = "".join(random.choice(string.ascii_lowercase) for _ in range(20))
        expected = self._expected_lps(s)
        self.assertEqual(solution(s), expected)

    def test_random_string_large(self):
        s = "".join(random.choice(string.ascii_lowercase) for _ in range(1000))
        expected = self._expected_lps(s)
        self.assertEqual(solution(s), expected)

    def test_edge_case_empty_string(self):
        self.assertEqual(solution(""), 0)

    def test_invalid_input_type(self):
        with self.assertRaises(TypeError):
            solution(12345)

    def test_invalid_characters(self):
        with self.assertRaises(ValueError):
            solution("abCde1")

    def test_long_even_length_string(self):
        s = "ab" * 500
        expected = 500
        self.assertEqual(solution(s), expected)

    def test_long_odd_length_string(self):
        s = ("abc" * 333) + "a"
        expected = self._expected_lps(s)
        self.assertEqual(solution(s), expected)

if __name__ == "__main__":
    unittest.main()
